PROGRAM ST230_MONTERING
VAR
    ST230_CLP_CLOSED : INT;
    ST230_RB_PRG     : BOOL;
    iSteg            : INT;
END_VAR

CASE iSteg OF
  0: ST230_RB_PRG   := TRUE;
     ST230_RB_START := ST230_PRT_A_PRS;
     IF ST230_RB_DONE THEN iSteg := 1; END_IF;
  1: ST230_CLP_CLOSE := TRUE;
     IF ST230_CLP_CLOSED > 0 THEN iSteg := 2; END_IF;
  2: ST230_RB_PRG   := FALSE;
     ST230_RB_START := TRUE;
     IF ST230_RB_DONE THEN iSteg := 0; END_IF;
END_CASE;
END_PROGRAM
